// FUT Forge SBC Midas runtime price cache.
// This symbol was referenced by the ID-mapping build but never declared.
const futforge_sbc_midas_price_cache_v1 = new Map();

const __ffMidasDiag = globalThis.__ffMidasDiag || (globalThis.__ffMidasDiag={
  version:"MIDAS_DIAGNOSTIC_V1", requests:0, requestedCards:0, responses:0,
  pricedCards:0, cacheHits:0, cacheMisses:0, lastStatus:null, lastError:null,
  lastSample:[], lastChosen:[], lastTotalCost:null
});
function __ffDiagLog(stage,data){
  try{
    console.log("[FUT Forge SBC MIDAS DIAG]",stage,data);
    globalThis.__ffMidasDiag.lastStage=stage;
    globalThis.__ffMidasDiag.lastData=data;
  }catch(_){}
}


const __ffExpandSbcSquad=(payload,squad)=>{
  const src=Array.isArray(squad)?squad:[];
  const pr=Array.isArray(payload?.playerRequirements)?payload.playerRequirements:[];
  if(!pr.length) return src;
  const out=Array.from({length:11},(_,index)=>({index,id:0}));
  const usable=pr.filter(x=>String(x?.playerType||"DEFAULT").toUpperCase()!=="BRICK")
                 .map(x=>Number(x.index)).filter(Number.isFinite);
  let cursor=0;
  for(const slot of usable){
    const p=src[cursor++];
    if(!p) break;
    out[slot]={index:slot,id:Number(p.id??p.itemId??0)};
  }
  return out;
};


// EA's real elgReq field for "Bronze/Silver/Gold: Min. N Players" is
// PLAYER_LEVEL (confirmed against a live Daily Silver Upgrade capture:
// PLAYER_COUNT=1 + PLAYER_LEVEL=2 + SCOPE=0, UI text "Silver: Min. 1
// Players") - NOT PLAYER_QUALITY, which does not appear anywhere in any
// real EA payload seen in this codebase. eligibilityValue=2 for "Silver"
// matches this 1/2/3 Bronze/Silver/Gold ordinal by rating bucket.
const __ffSbcPlayerLevelCode=(p)=>{
  const r=Number(p?.rating??p?._rating??p?.overallRating??p?.overall??0);
  if(r>0 && r<=64) return 1;   // Bronze
  if(r>=65 && r<=74) return 2; // Silver
  if(r>=75) return 3;          // Gold
  return 0;
};
const __ffSbcUsableSlots=(payload)=>{
  const pr=payload?.playerRequirements;
  if(!Array.isArray(pr)||!pr.length) return [...Array(11).keys()];
  return pr.filter(x=>String(x?.playerType||"DEFAULT").toUpperCase()!=="BRICK")
           .map(x=>Number(x.index)).filter(Number.isFinite);
};


const __ffNormalizeSbcItems=(src)=>{
  const a=Array.isArray(src)?src:[];
  const out=a.map(x=>{
    const item=x&&x.item?x.item:x;
    if(!item||typeof item!=="object")return null;
    const id=item.id??item.itemId??item.instanceId??x?.id;
    const definitionId=item.definitionId??item.resourceId??item.assetId??item.definition?.id??x?.definitionId;
    if(id==null||definitionId==null)return null;
    const groups=Object.freeze(Array.isArray(item.groups)?item.groups.slice():[]);
    return {
      ...item,
      id,
      definitionId,
      groups,
      _ffPile:item._ffPile??x?._ffPile??null,
     _ffPreferStorage:item._ffPreferStorage===true||x?._ffPreferStorage===true,
      _ffEaNormalGoldRare:item._ffEaNormalGoldRare===true,
      activeSquad:!!(item.activeSquad??item.isInActiveSquad),
      hasUpgrade:!!(item.hasUpgrade??item.upgrade),
      locked:!!(item.locked??item.isLocked),
      tradeable:!!(item.tradeable??item.isTradeable),
      isTransferOrUnassignedDuplicate:!!(item.isTransferOrUnassignedDuplicate??item.isDuplicate),
      limitedUseType:item.limitedUseType??null,
      ...(item.upgrade!=null?{upgrade:item.upgrade}:{})
    };
  }).filter(Boolean);
  return out;
};

