function ffEaSquadRating(arr){
 const rs=(Array.isArray(arr)?arr:[]).map(ffRating).filter(Number.isFinite);
 if(!rs.length)return 0;
 const avg=rs.reduce((a,b)=>a+b,0)/rs.length;
 const correction=rs.reduce((n,r)=>n+Math.max(0,r-avg),0)/rs.length;
 return Math.floor(avg+correction+1e-9);
}

function ffTrimEaRatingOverkill(chosen,reserve,target,lockedIds){
 if(!target)return chosen;
 const locked=lockedIds||new Set();
 let changed=true;
 while(changed){
  changed=false;
  chosen.sort((a,b)=>ffRating(b)-ffRating(a));
  reserve.sort((a,b)=>ffRating(a)-ffRating(b));
  outer:for(let ci=0;ci<chosen.length;ci++){
   if(locked.has(String(ffId(chosen[ci]))))continue;
   for(let ri=0;ri<reserve.length;ri++){
    if(ffRating(reserve[ri])>=ffRating(chosen[ci]))break;
    const trial=chosen.slice();trial[ci]=reserve[ri];
    if(ffEaSquadRating(trial)>=target){
      const old=chosen[ci];chosen[ci]=reserve[ri];reserve[ri]=old;changed=true;break outer;
    }
   }
  }
 }
 return chosen;
}
function ffOptimizeEaRating(players,size,target){
 const pool=players.slice().sort((a,b)=>ffRating(a)-ffRating(b));
 let chosen=pool.slice(0,size), reserve=pool.slice(size);
 if(!target||chosen.length<size)return chosen;
 let guard=0;
 while(ffEaSquadRating(chosen)<target && guard++<1000){
  let best=null,current=ffEaSquadRating(chosen);
  for(let ci=0;ci<chosen.length;ci++){
   for(let ri=0;ri<reserve.length;ri++){
    if(ffRating(reserve[ri])<=ffRating(chosen[ci]))continue;
    const trial=chosen.slice();trial[ci]=reserve[ri];
    const sr=ffEaSquadRating(trial);
    if(sr<=current)continue;
    const reaches=sr>=target;
    const score=(reaches?0:100000)+(reaches?(sr-target)*1000:0)+(ffRating(reserve[ri])-ffRating(chosen[ci]));
    if(!best||score<best.score)best={ci,ri,score};
    if(reaches)break;
   }
  }
  if(!best)break;
  const old=chosen[best.ci];chosen[best.ci]=reserve[best.ri];reserve[best.ri]=old;
  reserve.sort((a,b)=>ffRating(a)-ffRating(b));
 }
 return ffTrimEaRatingOverkill(chosen,reserve,target);
}

