   const get=t=>rs.find(r=>String(r?.type||"").toUpperCase()===t);
   const all=t=>rs.filter(r=>String(r?.type||"").toUpperCase()===t);
   const pc=get("PLAYER_COUNT");
   const leagueIds=all("LEAGUE_ID").map(r=>Number(r.eligibilityValue)).filter(Boolean);
   const nationIds=all("NATION_ID").map(r=>Number(r.eligibilityValue)).filter(Boolean);
   const clubIds=all("CLUB_ID").map(r=>Number(r.eligibilityValue)).filter(Boolean);
   const sameLeague=get("SAME_LEAGUE_COUNT"), sameNation=get("SAME_NATION_COUNT"), sameClub=get("SAME_CLUB_COUNT");
   const leagueCount=get("LEAGUE_COUNT"), nationCount=get("NATION_COUNT"), clubCount=get("CLUB_COUNT");
   const rarityGroup=get("PLAYER_RARITY_GROUP");
   const playerLevel=get("PLAYER_LEVEL");
   const rating=get("TEAM_RATING_1_TO_100"), chem=get("CHEMISTRY_POINTS");
   const scope=Number(get("SCOPE")?.eligibilityValue??0);
   // Multiple IDs in one EA eligibilitySlot are alternatives (OR), not separate requirements.
   if(pc&&leagueIds.length)return {slot,kind:"leagueMinPlayers",ids:leagueIds,id:leagueIds[0],value:Number(pc.eligibilityValue)};
   if(pc&&nationIds.length)return {slot,kind:"nationMinPlayers",ids:nationIds,id:nationIds[0],value:Number(pc.eligibilityValue)};
   if(pc&&clubIds.length)return {slot,kind:"clubMinPlayers",ids:clubIds,id:clubIds[0],value:Number(pc.eligibilityValue)};
   if(pc&&rarityGroup)return {slot,kind:"rarityGroupMin",groupId:Number(rarityGroup.eligibilityValue),value:Number(pc.eligibilityValue)};
   // "Silver: Min. N Players" (Bronze/Silver/Gold): PLAYER_LEVEL scoped by a
   // PLAYER_COUNT in the same eligibilitySlot - the exact same "Min N Players"
   // pairing pattern EA already uses for league/nation/club/rarity-group above.
   // Confirmed against a live Daily Silver Upgrade capture: real EA elgReq is
   // PLAYER_COUNT(1) + PLAYER_LEVEL(2) + SCOPE(0) in eligibilitySlot 1, UI text
   // "Silver: Min. 1 Players". An earlier version of this file guessed a
   // different, never-observed requirement type (PLAYER_QUALITY) for this same
   // UI text; that guess never matched real EA data, so the requirement fell
   // through to kind:"other" (silently ignored) - the actual root cause of a
   // real production bug: Auto Complete satisfied "Silver: Min. 1 Players"
   // with a Bronze card. Only the scoped Min-N form is modeled here, matching
   // every other scoped requirement in this function - there is no evidence of
   // an unscoped "entire squad must be this level" PLAYER_LEVEL requirement,
   // so one is not fabricated the way the removed PLAYER_QUALITY code did.
   // SCOPE=0 was observed in the real payload; per this function's existing
   // scope===1="Max" convention (used below for same-league/nation/club and
   // league/nation/club count) 0 reads as the default/Min scope, so no
   // separate handling is needed for the one real case captured so far. If a
   // genuine "Max N" PLAYER_LEVEL payload is ever observed, extend this the
   // same way the Max variants below were added - do not guess it now.
   if(pc&&playerLevel)return {slot,kind:"playerLevelMinPlayers",levelCode:Number(playerLevel.eligibilityValue),value:Number(pc.eligibilityValue)};
   if(sameLeague)return {slot,kind:scope===1?"sameLeagueMax":"sameLeagueMin",value:Number(sameLeague.eligibilityValue)};
   if(sameNation)return {slot,kind:scope===1?"sameNationMax":"sameNationMin",value:Number(sameNation.eligibilityValue)};
   if(sameClub)return {slot,kind:scope===1?"sameClubMax":"sameClubMin",value:Number(sameClub.eligibilityValue)};
   if(leagueCount)return {slot,kind:scope===1?"leagueCountMax":"leagueCountMin",value:Number(leagueCount.eligibilityValue)};
   if(nationCount)return {slot,kind:scope===1?"nationCountMax":"nationCountMin",value:Number(nationCount.eligibilityValue)};
   if(clubCount)return {slot,kind:scope===1?"clubCountMax":"clubCountMin",value:Number(clubCount.eligibilityValue)};
   if(rating)return {slot,kind:"ratingMin",value:Number(rating.eligibilityValue)};
   if(chem)return {slot,kind:"chemMin",value:Number(chem.eligibilityValue)};
