 if(g.kind==="nationMinPlayers")return arr.filter(p=>(g.ids||[g.id]).includes(__ffNation(p))).length>=g.value;
 if(g.kind==="clubMinPlayers")return arr.filter(p=>(g.ids||[g.id]).includes(__ffClub(p))).length>=g.value;
 if(g.kind==="sameLeagueMin")return maxOf(__ffLeague)>=g.value;
 if(g.kind==="sameLeagueMax")return maxOf(__ffLeague)<=g.value;
 if(g.kind==="sameNationMin")return maxOf(__ffNation)>=g.value;
 if(g.kind==="sameNationMax")return maxOf(__ffNation)<=g.value;
 if(g.kind==="sameClubMin")return maxOf(__ffClub)>=g.value;
 if(g.kind==="sameClubMax")return maxOf(__ffClub)<=g.value;
 if(g.kind==="rarityGroupMin")return arr.filter(p=>__ffBelongsToRarityGroup(p,g.groupId)).length>=g.value;
 if(g.kind==="playerLevelMinPlayers")return arr.filter(p=>__ffSbcPlayerLevelCode(p)===g.levelCode).length>=g.value;
 if(g.kind==="leagueCountMin")return __ffDistinct(arr,__ffLeague)>=g.value;
 if(g.kind==="leagueCountMax")return __ffDistinct(arr,__ffLeague)<=g.value;
 if(g.kind==="nationCountMin")return __ffDistinct(arr,__ffNation)>=g.value;
 if(g.kind==="nationCountMax")return __ffDistinct(arr,__ffNation)<=g.value;
 if(g.kind==="clubCountMin")return __ffDistinct(arr,__ffClub)>=g.value;
 if(g.kind==="clubCountMax")return __ffDistinct(arr,__ffClub)<=g.value;
 if(g.kind==="ratingMin")return ffEaSquadRating(arr)>=g.value;
 if(g.kind==="chemMin"){const __slots=(globalThis.__ffCurrentChemSlots||[]).slice(0,arr.length);return __slots.length===arr.length?__ffEaChemistry(arr,__slots).total>=g.value:false;}
