 const maxOf=fn=>Math.max(0,...counts(fn).values());
 const distinct=fn=>counts(fn).size;
 if(g.kind==="leagueMinPlayers")return Math.min(g.value,arr.filter(p=>(g.ids||[g.id]).includes(__ffLeague(p))).length)/Math.max(1,g.value);
 if(g.kind==="nationMinPlayers")return Math.min(g.value,arr.filter(p=>(g.ids||[g.id]).includes(__ffNation(p))).length)/Math.max(1,g.value);
 if(g.kind==="clubMinPlayers")return Math.min(g.value,arr.filter(p=>(g.ids||[g.id]).includes(__ffClub(p))).length)/Math.max(1,g.value);
 if(g.kind==="sameLeagueMin")return Math.min(g.value,maxOf(__ffLeague))/Math.max(1,g.value);
 if(g.kind==="sameNationMin")return Math.min(g.value,maxOf(__ffNation))/Math.max(1,g.value);
 if(g.kind==="sameClubMin")return Math.min(g.value,maxOf(__ffClub))/Math.max(1,g.value);
 if(g.kind==="rarityGroupMin")return Math.min(g.value,arr.filter(p=>__ffBelongsToRarityGroup(p,g.groupId)).length)/Math.max(1,g.value);
 if(g.kind==="playerLevelMinPlayers")return Math.min(g.value,arr.filter(p=>__ffSbcPlayerLevelCode(p)===g.levelCode).length)/Math.max(1,g.value);
