// LIVE SQUAD PRICE ENGINE — dopo ogni sostituzione manuale la rosa EA corrente
// torna ad essere l'unica fonte di verità per prezzi e badge.
function ffGetLiveSbcSquadItems(){
 try{
  const d=globalThis.FutForgeDispatcher;
  const roots=[];
  try{const c=d?.getCurrentController?.(); if(c){roots.push(c,c.current,c.leftController,c.rightController,c.primaryController,c.splitController)}}catch(_){}
  try{const v=d?.getCurrentViews?.(); if(v)roots.push(v,v.primaryController,v.leftDeepestController,v.rightDeepestController,v.leftController,v.rightController)}catch(_){}
  // Do NOT trust the first controller exposing a partial squad. EA keeps several
  // controllers alive during Club Search. Collect every candidate and use the
  // fullest 11-player squad only. V7 returned after the first item, which is why
  // a manual swap could wipe the other ten price badges and corrupt the total.
  const candidates=[];
  const seen=new Set();
  const inspect=(ctl)=>{
   if(!ctl||seen.has(ctl))return; seen.add(ctl);
   const objects=[ctl,ctl._challenge,ctl.challenge,ctl.sbcViewModel,ctl._sbcViewModel].filter(Boolean);
   for(const o of objects){
    const sq=o?.squad||o?._squad||o?.challenge?.squad||null;
    if(!sq)continue;
    const out=[];
    for(let slot=0;slot<11;slot++){
      let item=null;
      try{if(typeof sq.getItemForSlot==='function')item=sq.getItemForSlot(slot)}catch(_){}
      try{if(!item&&typeof sq.getSlot==='function'){const sl=sq.getSlot(slot);item=sl&&typeof sl.getItem==='function'?sl.getItem():sl?.item}}catch(_){}
      if(item)out.push(item);
    }
    if(out.length)candidates.push(out);
    for(const key of ['players','items']){
      const a=Array.isArray(sq?.[key])?sq[key].map(x=>x?.item||x).filter(Boolean):[];
      if(a.length)candidates.push(a);
    }
   }
  };
  roots.filter(Boolean).forEach(inspect);
  candidates.sort((a,b)=>b.length-a.length);
  const full=candidates.find(a=>a.length===11 && new Set(a.map(x=>String(ffId(x)||ffDefId(x)))).size===11);
  return full||[];
 }catch(_){return []}
}
function ffRefreshLiveSbcMarketState(){
 try{
  const items=ffGetLiveSbcSquadItems();
  if(items.length!==11)return null;
  const sig=items.map(x=>String(ffId(x)||ffDefId(x))+':'+String(ffProviderMarketValue(x)||0)).join('|');
  if(sig===globalThis.__ffLiveSbcSig)return null;
  globalThis.__ffLiveSbcSig=sig;
  const totalState=ffUpdateTotalSquadPrice(items);
  const md=items.map(x=>({definitionId:ffDefId(x),price:ffProviderMarketValue(x)}));
  // V9: never redraw card price badges from the polling loop. During Club Search EA
  // keeps transient/partial view models alive; touching those tiles was the cause of
  // disappearing/stale values after a manual replacement. Native EA remains owner of
  // the XI DOM; this loop updates only the aggregate market total.
  // Tiene il totale vivo mentre EA ridisegna la schermata dopo lo swap.
  ffKeepTotalSquadPriceAlive(totalState.total,totalState.unavailable);
  globalThis.__FUTFORGE_LIVE_SQUAD_STATE__={ts:Date.now(),count:items.length,signature:sig,total:totalState.total,unavailable:totalState.unavailable};
  return globalThis.__FUTFORGE_LIVE_SQUAD_STATE__;
 }catch(e){console.warn('[FUT Forge Live Squad Price]',e);return null}
}
setInterval(ffRefreshLiveSbcMarketState,700);
globalThis.FUTFORGE_LIVE_SQUAD_DIAG=()=>JSON.parse(JSON.stringify(globalThis.__FUTFORGE_LIVE_SQUAD_STATE__||{}));

globalThis.FUTFORGE_SBC_UNIQUE_DIAG=()=>{
 const d=globalThis.__FUTFORGE_LAST_SOLVER_COST__||{};
 const a=Array.isArray(d.players)?d.players:[];
 const seen=new Map(),duplicates=[];
 for(const p of a){
   const k=String(p.definitionId||p.id||0);
   if(seen.has(k))duplicates.push({definitionId:p.definitionId,first:seen.get(k),duplicate:p});
   else seen.set(k,p);
 }
 return {count:a.length,unique:seen.size,duplicates,valid:duplicates.length===0};
};


function ffRenderSbcPriceBadges(solution){
 try{
  document.querySelectorAll(".futforge-sbc-price-badge").forEach(x=>x.remove());
  const md=solution?.marketDetail||[];
  if(!md.length)return;
  const candidates=[...document.querySelectorAll("[data-definition-id],[data-resource-id],[data-item-id]")];
  for(const d of md){
   const def=String(d.definitionId||"");
   let el=candidates.find(x=>String(x.getAttribute("data-definition-id")||x.getAttribute("data-resource-id")||"")===def);
   if(!el)continue;
   const host=el.closest("li, .ut-item-view, .player-item, [class*='player']")||el.parentElement;
   if(!host)continue;
   if(getComputedStyle(host).position==="static")host.style.position="relative";
   const b=document.createElement("div");
   b.className="futforge-sbc-price-badge";
   if(d.price>0){
     const num=document.createElement("span");
     num.textContent=Number(d.price).toLocaleString("it-IT");
     const img=document.createElement("img");
     img.src="data:image/png;base64,";
     img.alt="";
     Object.assign(img.style,{width:"11px",height:"11px",objectFit:"contain",marginLeft:"3px",verticalAlign:"-1px"});
     b.append(num,img);
   }else{
     b.textContent="N/A";
   }
   Object.assign(b.style,{
     position:"absolute",left:"50%",transform:"translateX(-50%)",
     bottom:"-8px",zIndex:"9999",padding:"2px 6px",borderRadius:"5px",
     background:"rgba(5,14,25,.92)",border:"1px solid rgba(255,215,64,.65)",
     color:"#fff",fontSize:"10px",fontWeight:"700",whiteSpace:"nowrap",
     pointerEvents:"none"
   });
   host.appendChild(b);
  }
 }catch(_){}
}

